    def pacificAtlantic(self, heights):
        rows = len(heights)
        cols = len(heights[0])

        result = []

        def can_reach(r, c, target):
            visited = set()

            def dfs(x, y):
                if (x, y) in visited:
                    return False

                if target == "P" and (x == 0 or y == 0):
                    return True

                if target == "A" and (
                    x == rows - 1 or y == cols - 1
                ):
                    return True

                visited.add((x, y))

                for dx, dy in [
                    (1, 0), (-1, 0),
                    (0, 1), (0, -1)
                ]:
                    nx, ny = x + dx, y + dy

                    if (
                        0 <= nx < rows and
                        0 <= ny < cols and
                        heights[nx][ny] <= heights[x][y]
                    ):
                        if dfs(nx, ny):
                            return True

                return False

            return dfs(r, c)

        for r in range(rows):
            for c in range(cols):
                if (
                    can_reach(r, c, "P")
                    and can_reach(r, c, "A")
                ):
                    result.append([r, c])

        return result

