from collections import deque

class Solution:
    def pacificAtlantic(self, heights):
        rows = len(heights)
        cols = len(heights[0])

        def bfs(starts):
            visited = set()
            queue = deque(starts)

            for cell in starts:
                visited.add(cell)

            while queue:
                r, c = queue.popleft()

                for dr, dc in [
                    (1, 0), (-1, 0),
                    (0, 1), (0, -1)
                ]:
                    nr, nc = r + dr, c + dc

                    if (
                        0 <= nr < rows and
                        0 <= nc < cols
                        and (nr, nc) not in visited
                        and heights[nr][nc] >= heights[r][c]
                    ):
                        visited.add((nr, nc))
                        queue.append((nr, nc))

            return visited

        pacific = []

        for r in range(rows):
            pacific.append((r, 0))

        for c in range(cols):
            pacific.append((0, c))

        atlantic = []

        for r in range(rows):
            atlantic.append((r, cols - 1))

        for c in range(cols):
            atlantic.append((rows - 1, c))

        p = bfs(pacific)
        a = bfs(atlantic)

        return [
            [r, c]
            for r, c in p & a
        ]

