                        if (
                            0 <= nr < rows and
                            0 <= nc < cols and
                            grid[nr][nc] == 1
                        ):
                            grid[nr][nc] = 3  # rots this minute, spreads next minute
                            changed = True

            if not changed:
                break

            for row in grid:
                for c in range(cols):
                    if row[c] == 3:
                        row[c] = 2

            minutes += 1

        for row in grid:
            if 1 in row:
                return -1

        return minutes

